"""Read-only runtime discovery; create-only candidate assessment and policy."""
import sys,json,hashlib,platform,shutil,importlib.util,importlib.metadata,datetime
from pathlib import Path
import select_profile as s

def main():
    base=s.ROOT/'docs/plans/definition-formal-assurance/candidate/assurance-snapshots-v1';impl=s.IMPL
    sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
    python=Path(sys.executable).resolve();python_ref={'path':str(python),'sha256':sha(python)}
    code=[s.binding(impl/p) for p in ['contracts.py','resolver.py','ir.py','semantics.py']]
    jsonschema=Path(importlib.util.find_spec('jsonschema').origin)
    runtime_bindings=[python_ref,{'path':str(jsonschema),'sha256':sha(jsonschema)}]
    commands={name:shutil.which(name) for name in ['python3','lean','lake','elan','z3','cvc5']}
    modules={name:(importlib.util.find_spec(name).origin if importlib.util.find_spec(name) else None) for name in ['jsonschema','z3','cvc5']}
    if any(commands[name] is not None for name in ['lean','lake','elan','z3','cvc5']) or modules['z3'] or modules['cvc5']:raise RuntimeError('Observed runtime discovery changed; reassess rather than reuse missing-runtime declarations.')
    routes={
      'static-model-evaluator':{'runtime_available':True,'adapter_available':True,'lowering_status':'implemented-static','runtime_bindings':runtime_bindings,'adapter_bindings':code,'discovery_scope':'Exact active Python executable and candidate static evaluator modules; no generic search.','diagnostics':[]},
      'generic-finite':{'runtime_available':True,'adapter_available':False,'lowering_status':'pending-exact-lowering','runtime_bindings':runtime_bindings,'adapter_bindings':[],'discovery_scope':'Current Python available; generic provider output P02 is not present.','diagnostics':[{'code':'P02-generic-finite-provider-not-implemented'}]},
      'smt-projection':{'runtime_available':False,'adapter_available':False,'lowering_status':'pending-exact-lowering','runtime_bindings':[],'adapter_bindings':[],'discovery_scope':'Current PATH z3/cvc5 and active Python import resolution z3/cvc5; no claim about every installed filesystem or remote runtime.','diagnostics':[{'code':'no-SMT-in-checked-PATH-or-Python-resolution'},{'code':'P03-exact-projection-not-implemented'}]},
      'proof-kernel':{'runtime_available':False,'adapter_available':False,'lowering_status':'pending-exact-lowering','runtime_bindings':[],'adapter_bindings':[],'discovery_scope':'Current PATH lean/lake/elan; imported Lean source/profile and pinned toolchain are design leads, not execution bindings.','diagnostics':[{'code':'no-Lean-in-checked-PATH'},{'code':'P04-exact-theorem-route-not-implemented'}]}}
    assessment={'schema_version':'definition-assurance-tooling-assessment/v1-candidate','authority_effect':'none','observed_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'runtime':{'python_version':platform.python_version(),'python_executable':str(python),'python_executable_sha256':sha(python),'jsonschema_version':importlib.metadata.version('jsonschema'),'platform':platform.platform()},'discovery':{'commands':commands,'python_modules':modules,'scope_ceiling':'Discovery is limited to active PATH/import resolution; no universal missing-installation assertion.'},'routes':routes,'bound_context_leads':[s.binding(s.ROOT/'craft/formalization/profiles/formal-language-profiles.json'),s.binding(s.ROOT/'craft/formalization/candidates/relational-theorem-checker/v1/formal/lean-toolchain')],'non_readiness':['No current-source universal theorem or generic mechanized evaluator correctness proof.','Imported theorem/profile admissions concern exact other subjects; not inherited for these 183 definitions.','Available Python and successful static controls do not mean generic finite/SMT/kernel adapters are implemented.'],'claim_ceiling':'Local exact candidate capability and discovery assessment; no installation, provider theorem, source fidelity, admission or production authority.'}
    def write(path,obj):
        with path.open('x') as f:json.dump(obj,f,indent=2,sort_keys=True);f.write('\n')
    write(base/'tooling-assessment.json',assessment)
    ceilings={'static-model-evaluator':'Truth in an exact supplied complete finite structure only.','generic-finite':'Checked exact witness or exhaustive absence inside the exact enumerated finite domain scope; no unbounded absence.','smt-projection':'Exact solver/projected formula evidence under separately established encoding and runtime; cannot satisfy mechanized-theorem minimum by a solver label.','proof-kernel':'Exact kernel-checked proposition under bound imports, assumptions, options and translation; no automatic source fidelity.'}
    policy={'schema_version':'definition-assurance-provider-selection/v1-candidate','authority_effect':'none','logic':{'supported_core':sorted(s.STATIC),'extensions':'inductive-fixed-point, temporal, normative-deontic and empirical-probabilistic need separate selected semantics and exact lowering before execution'},'minimum_strengths':s.MINIMUMS,'routes':{name:{'logic_features':sorted(s.STATIC),'strengths':strengths,'implementation_unit':unit,'required_runtime':runtime,'claim_ceiling':ceilings[name]} for name,strengths,unit,runtime in [('static-model-evaluator',['model-local-value'],'C02','python-current-bound'),('generic-finite',['model-witness','bounded-exhaustion'],'P02','python-current-bound'),('smt-projection',['model-witness','solver-evidence'],'P03','exact-isolated-SMT-runtime-required'),('proof-kernel',['mechanized-theorem'],'P04','exact-isolated-Lean-runtime-required')]},'budgets':{'timeout_seconds':30,'max_interpretations':10000,'max_evaluation_steps':100000,'max_function_tuple_space':100000,'max_output_bytes':1000000,'max_domain_cardinality':3,'execution_policy':'declared-for-later-adapters; not proof of current enforcement'},'install_policy':'no-installs-in-P01; future isolated exact-runtime task required','inventory_ref':s.binding(base/'tooling-assessment.json'),'claim_ceiling':'Candidate route selection and declarative resource bounds; no logical verdict, source meaning acceptance, installation or runtime authority.'}
    s.validate_policy(policy);s.verify_inventory(assessment)
    write(impl/'profiles/selection.json',policy)
    print(json.dumps({'python':assessment['runtime']['python_version'],'jsonschema':assessment['runtime']['jsonschema_version'],'routes':{name:{key:row[key] for key in ['runtime_available','adapter_available']} for name,row in routes.items()}},indent=2))

if __name__=='__main__':main()
